// Event-driven 2D menu; no continuous animation or WebGL work.
export function mountSettings(dialog,api){const canvas=dialog.querySelector('canvas'),ctx=canvas.getContext('2d'),win=dialog.ownerDocument.defaultView;let tab=1,focus=0,scroll=0,capture=null,message='',hits=[],rows=[],visible=1,drag=null;
const tabs=()=>['Général','Audio','Touches','Vidéo','Confort',api.mj()?'MJ':'Joueur'];
function draw(){if(!dialog.open||!ctx)return;const r=canvas.getBoundingClientRect(),w=r.width,h=r.height,d=Math.min(2,win.devicePixelRatio||1);if(!w||!h)return;if(canvas.width!==Math.round(w*d)||canvas.height!==Math.round(h*d)){canvas.width=Math.round(w*d);canvas.height=Math.round(h*d)}ctx.setTransform(d,0,0,d,0,0);hits=[];rows=api.rows(tab);visible=Math.max(1,Math.floor((h-150)/44));focus=Math.max(0,Math.min(focus,rows.length-1));scroll=Math.max(0,Math.min(scroll,Math.max(0,rows.length-visible)));if(focus<scroll)scroll=focus;if(focus>=scroll+visible)scroll=focus-visible+1;
const rect=(x,y,w,h,c)=>{ctx.fillStyle=c;ctx.fillRect(x,y,w,h)},text=(t,x,y,size=13,c='#e9e4d5',max=Infinity)=>{ctx.font=size+'px system-ui';ctx.fillStyle=c;t=String(t);while(t.length>1&&ctx.measureText(t).width>max)t=t.slice(0,-2)+'…';ctx.fillText(t,x,y)},hit=(x,y,w,h,fn)=>hits.push({x,y,w,h,fn});
rect(0,0,w,h,'#131b19');rect(0,0,w,68,'#202e27');text('LES BRUMES  /  '+(api.mj()?'MJ':'JOUEUR'),18,22,11,'#c6ae75');text('Paramètres',18,51,24);const tw=(w-20)/6;tabs().forEach((name,i)=>{const x=10+i*tw;rect(x,76,tw-3,30,i===tab?'#50604a':'#26352e');text(name,x+6,95,12,'#eee4cb',tw-14);hit(x,76,tw-3,30,()=>{tab=i;focus=scroll=0;capture=null;message='';draw()})});
for(let j=0;j<visible&&scroll+j<rows.length;j++){const i=scroll+j,a=rows[i],y=112+j*44,x=Math.floor(w*.56),cw=w-x-24;rect(10,y,w-20,40,i===focus?'#30443a':'#202c26');text(a.label,20,y+24,13,'#ece6d8',x-30);if(a.type==='range'){const bw=Math.max(18,cw-53),t=(a.value-a.min)/(a.max-a.min);rect(x,y+19,bw,5,'#526056');rect(x,y+19,bw*t,5,'#c6ae75');rect(x+bw*t-3,y+15,7,13,'#f0dfb2');text(a.format(a.value),x+bw+8,y+24,12);const change=px=>{const v=a.min+(a.max-a.min)*Math.max(0,Math.min(1,(px-x)/bw));a.set(Number((Math.round((v-a.min)/a.step)*a.step+a.min).toFixed(3)));draw()};hit(x,y,cw,40,px=>{focus=i;drag=change;change(px)})}else{rect(x,y+6,cw,28,'#36463c');text(capture===a.id?'Appuyez sur une touche':a.type==='toggle'?(a.value?'Activé':'Désactivé'):a.type==='choice'?a.options.find(o=>o[0]===a.value)?.[1]:a.value,x+7,y+24,12,'#f0dfb2',cw-14);hit(x,y,cw,40,()=>{focus=i;activate(a,1)})}}
rect(0,h-32,w,32,'#202e27');text(message||'↑ ↓ Naviguer · ← → Régler · Page ↑ ↓ Onglets · Échap',12,h-11,11,'#c6ae75',w-24);
}
function activate(a,dir){if(!a)return;message='';if(a.type==='toggle')a.set(!a.value);else if(a.type==='range')a.set(Math.max(a.min,Math.min(a.max,Number((a.value+dir*a.step).toFixed(3)))));else if(a.type==='choice'){let i=a.options.findIndex(o=>o[0]===a.value);a.set(a.options[(i+dir+a.options.length)%a.options.length][0])}else if(a.type==='binding')capture=a.id;else a.run?.();draw()}
const point=e=>{const r=canvas.getBoundingClientRect();return [e.clientX-r.left,e.clientY-r.top]};canvas.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();canvas.focus();const [x,y]=point(e),a=hits.find(a=>x>=a.x&&x<a.x+a.w&&y>=a.y&&y<a.y+a.h);if(a){capture=null;a.fn(x);if(drag)canvas.setPointerCapture?.(e.pointerId)}};canvas.onpointermove=e=>{if(drag)drag(point(e)[0])};canvas.onpointerup=canvas.onpointercancel=canvas.onlostpointercapture=()=>drag=null;canvas.addEventListener('wheel',e=>{e.preventDefault();focus=Math.max(0,Math.min(rows.length-1,focus+Math.sign(e.deltaY)*2));draw()},{passive:false});dialog.onkeydown=e=>{if(e.key==='Tab'&&!capture)return;e.preventDefault();e.stopPropagation();if(capture){if(e.key==='Escape'){capture=null;message=''}else{message=api.bind(capture,e.code)||'Touche enregistrée';if(message==='Touche enregistrée')capture=null}draw();return}if(e.key==='Escape'||e.key==='F10'){dialog.close();return}if(['PageUp','PageDown'].includes(e.key)){tab=(tab+(e.key==='PageUp'?5:1))%6;focus=scroll=0;draw()}else if(['ArrowUp','ArrowDown'].includes(e.key)){focus=Math.max(0,Math.min(rows.length-1,focus+(e.key==='ArrowUp'?-1:1)));draw()}else if(['ArrowLeft','ArrowRight','Enter',' '].includes(e.key))activate(rows[focus],e.key==='ArrowLeft'?-1:1)};dialog.querySelector('button').onclick=()=>dialog.close();dialog.onclose=()=>{capture=drag=null;api.close()};new win.ResizeObserver(draw).observe(canvas);return{get open(){return dialog.open},show(){if(dialog.open)return;api.open();dialog.showModal();canvas.focus();draw()},draw}}
